package com.greenocean.backend.professional.service;
import javax.crypto.Cipher;import javax.crypto.spec.GCMParameterSpec;import javax.crypto.spec.SecretKeySpec;import java.security.SecureRandom;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;
/** Versioned authenticated envelope. Production key provisioning/rotation remains an explicit operations prerequisite. */
public final class PrivateDocumentCipher {
 private final Map<String,byte[]> keys=new HashMap<>();private final String current;
 public PrivateDocumentCipher(String keyring,String current){this.current=current;for(String entry:Objects.toString(keyring,"").split(",")){if(entry.isBlank())continue;String[] p=entry.split(":",2);if(p.length!=2||!p[0].matches("[A-Za-z0-9_-]{1,80}"))throw new IllegalArgumentException("Invalid private document key ring");byte[] key=Base64.getDecoder().decode(p[1]);if(key.length!=32)throw new IllegalArgumentException("Use a256-bit document encryption key");keys.put(p[0],key);}}
 public String current(){if(!keys.containsKey(current))throw new com.greenocean.backend.listener.live.LiveSupportException(503,"DOCUMENT_KEY_UNAVAILABLE","Encrypted document storage is not configured");return current;}
 public byte[] seal(byte[] plain,String purpose){try{String id=current();byte[] name=id.getBytes(StandardCharsets.UTF_8),nonce=new byte[12];new SecureRandom().nextBytes(nonce);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(keys.get(id),"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(purpose.getBytes(StandardCharsets.UTF_8));byte[] body=cipher.doFinal(plain);return ByteBuffer.allocate(4+1+name.length+nonce.length+body.length).putInt(0x474f4331).put((byte)name.length).put(name).put(nonce).put(body).array();}catch(com.greenocean.backend.listener.live.LiveSupportException e){throw e;}catch(Exception e){throw new IllegalStateException("Private document encryption failed",e);}}
 public byte[] open(byte[] sealed,String purpose){try{var b=ByteBuffer.wrap(sealed);if(b.getInt()!=0x474f4331)throw new IllegalArgumentException("Legacy unencrypted document is quarantined");int length=Byte.toUnsignedInt(b.get());if(length<1||length>80||b.remaining()<length+28)throw new IllegalArgumentException("Invalid document envelope");byte[] name=new byte[length],nonce=new byte[12];b.get(name);b.get(nonce);byte[] key=keys.get(new String(name,StandardCharsets.UTF_8));if(key==null)throw new IllegalStateException("Required document key is unavailable");byte[] body=new byte[b.remaining()];b.get(body);var cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,new SecretKeySpec(key,"AES"),new GCMParameterSpec(128,nonce));cipher.updateAAD(purpose.getBytes(StandardCharsets.UTF_8));return cipher.doFinal(body);}catch(Exception e){throw new IllegalStateException("Private document could not be authenticated",e);}}
}
